/// Initialises a fresh PostgreSQL database, creates the bench index, and
/// pre-seeds entries for read benchmarks.
async fn setup_datastore() -> (
    Arc<PostgresDatastore>,
    String,    // index_name
    Uuid,      // seed_key  (single-entry reads)
    Vec<Uuid>, // bulk_seed_keys
    String,    // db_name for cleanup
) {
    let fixtures = init_postgres().await;
    let datastore = Arc::new(fixtures.0);
    let db_name = fixtures.2;

    let index_name = format!("{}-index", ID_PREFIX);

    // Create the bench index (required before inserting entries).
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .expect("system time");
    datastore
        .create_index(Index {
            name: index_name.clone(),
            description: "Benchmark index".to_string(),
            max_bulk_operations: 1000,
            max_key_length: 256,
            max_value_length: 1024,
            max_kv_pairs_per_context: 10,
            hash_algorithm: HashAlgorithm::Xxh3 as i32,
            created_at: Some(udex_api::protobuf::Timestamp {
                seconds: now.as_secs() as i64,
                nanos: now.subsec_nanos() as i32,
            }),
            created_by: "bench-runner".to_string(),
            updated_at: None,
            updated_by: None,
        })
        .await
        .expect("create bench index");

    // Seed one entry for single-entry read benchmarks.
    let seed_key = Uuid::new_v4();
    datastore
        .create_entry(Entry {
            key: seed_key,
            context: Context {
                hash: "bench-seed-context".to_string(),
                pairs: vec![KeyValuePair {
                    key: "bench_user_id".to_string(),
                    value: Some(Value {
                        value: Some(udex_api::entry::value::Value::StringValue(
                            "bench_user_001".to_string(),
                        )),
                    }),
                    kek_id: None,
                    dek: None,
                }],
            },
            index_name: index_name.clone(),
        })
        .await
        .expect("create seed entry");

    // Seed BULK_SEED_COUNT entries for bulk read benchmarks.
    // Each entry gets a unique context so all inserts land as distinct rows.
    let bulk_seed_keys: Vec<Uuid> = (0..BULK_SEED_COUNT).map(|_| Uuid::new_v4()).collect();
    let bulk_ops: Vec<EntryWriteOperation> = bulk_seed_keys
        .iter()
        .enumerate()
        .map(|(i, &key)| {
            EntryWriteOperation::Create(Entry {
                key,
                context: Context {
                    hash: format!("bench-bulk-seed-context-{}", i),
                    pairs: vec![KeyValuePair {
                        key: "bench_iter".to_string(),
                        value: Some(Value {
                            value: Some(udex_api::entry::value::Value::StringValue(i.to_string())),
                        }),
                        kek_id: None,
                        dek: None,
                    }],
                },
                index_name: index_name.clone(),
            })
        })
        .collect();
    datastore
        .bulk_entry_write(bulk_ops)
        .await
        .expect("bulk seed entries");

    (datastore, index_name, seed_key, bulk_seed_keys, db_name)
}

